#include <TFT_eSPI.h>

TFT_eSPI tft = TFT_eSPI();

const uint16_t BG_COLOR = TFT_BLACK;
const uint16_t EYE_COLOR = TFT_WHITE;
const uint16_t PUPIL_COLOR = TFT_BLUE;

const int EYE_R = 38;
const int PUPIL_R = 14;
const int GAP = 20;

int cx, cy;
bool blinking = false;
unsigned long blinkStart = 0, nextBlink = 0, nextGlance = 0;
int pupX = 0, pupY = 0;

void drawEye(int ex, int ey, int dx, int dy, int blink) {
  int rH = EYE_R * (100 - blink) / 100;
  if (rH < 2) rH = 2;
  tft.fillCircle(ex, cy, EYE_R + 2, BG_COLOR);
  tft.fillEllipse(ex, ey, EYE_R, rH, EYE_COLOR);
  int pr = PUPIL_R * (100 - blink) / 100;
  if (pr > 1) {
    int px = constrain(ex + dx, ex - (EYE_R - PUPIL_R), ex + (EYE_R - PUPIL_R));
    int py = constrain(ey + dy, ey - (rH - PUPIL_R), ey + (rH - PUPIL_R));
    tft.fillCircle(px, py, pr, PUPIL_COLOR);
    tft.fillCircle(px - 4, py - 4, 3, TFT_WHITE);
  }
}

void drawAll() {
  int b = blinking ? 100 : 0;
  drawEye(cx - GAP - EYE_R, cy, pupX, pupY, b);
  drawEye(cx + GAP + EYE_R, cy, pupX, pupY, b);
}

void setup() {
  tft.init();
  tft.setRotation(1);
  cx = tft.width() / 2;
  cy = tft.height() / 2;
  tft.fillScreen(BG_COLOR);
  drawAll();
  nextBlink = millis() + random(2000, 6000);
  nextGlance = millis() + random(1500, 4000);
}

void loop() {
  unsigned long now = millis();
  if (blinking && now - blinkStart > 120) {
    blinking = false;
    drawAll();
    nextBlink = now + random(2000, 6000);
  }
  if (!blinking && now > nextBlink) {
    blinking = true;
    blinkStart = now;
    drawAll();
  }
  if (now > nextGlance) {
    pupX = random(-10, 11);
    pupY = random(-6, 7);
    if (random(10) == 0) { pupX = 0; pupY = 0; }
    drawAll();
    nextGlance = now + random(1500, 4000);
  }
}
